INSERT INTO permissions(code) VALUES ('payroll.view'),('payroll.create_period'),('payroll.compute'),('payroll.recompute'),('payroll.review'),('payroll.finalize'),('earnings.view'),('earnings.manage'),('deductions.view'),('deductions.manage'),('contributions.view'),('contributions.configure'),('tax.view'),('tax.configure');
INSERT INTO role_permissions SELECT r.id,p.code FROM roles r CROSS JOIN permissions p WHERE r.code IN ('administrator','payroll_manager') AND (p.code LIKE 'payroll.%' OR p.code LIKE 'earnings.%' OR p.code LIKE 'deductions.%' OR p.code LIKE 'contributions.%' OR p.code LIKE 'tax.%') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.code FROM roles r CROSS JOIN permissions p WHERE r.code IN ('payroll_clerk','viewer') AND p.code IN ('payroll.view','earnings.view','deductions.view','contributions.view','tax.view') ON CONFLICT DO NOTHING;
INSERT INTO role_permissions SELECT r.id,p.code FROM roles r CROSS JOIN permissions p WHERE r.code='payroll_clerk' AND p.code IN ('payroll.create_period','payroll.compute','payroll.recompute','earnings.manage','deductions.manage') ON CONFLICT DO NOTHING;
